/**
 * Get metadata for a specific model
 */
export function getModelMetadata(modelId: AllModels): ModelMetadata | undefined {
  return modelMetadata.find((m) => m.id === modelId);
}

/**
 * Get all models for a specific provider
 */
export function getModelsByProvider(provider: Provider): readonly ModelMetadata[] {
  return modelMetadata.filter((m) => m.provider === provider);
}

/**
 * Check if a string is a valid model identifier
 */
export function isValidModel(modelId: string): modelId is AllModels {
  return allModels.includes(modelId as AllModels);
}

/**
 * Parse a model identifier into provider and model name
 */
export function parseModelId(modelId: AllModels): { provider: Provider; model: string } {
  const match = modelId.match(/^@([^/]+)\/(.+)$/);
  if (!match || !match[1] || !match[2]) throw new Error(`Invalid model ID format: ${modelId}`);
  return { provider: match[1] as Provider, model: match[2] };
}
